SELECT ?show ?host ?hostingCount WHERE {
  ?appearance a TelevisionAppearance ;
              performer "Paul Melba" ;
              show ?show .
  ?show a TVShow ;
        country "UK" ;
        host ?host .
  ?host a Person ;
        name ?hostName ;
        hostedShowCount ?hostingCount .
  FILTER(?hostingCount = 23)
}

SELECT ?actress ?debutFilm ?debutDirector ?directorNationality ?starredInDonovan WHERE {
  ?actress wdt:P31 wd:Q5.  # instance of human
  ?debutFilm wdt:P166 ?actress.
  ?debutFilm wdt:P57 ?debutDirector.
  ?debutDirector wdt:P27 ?directorNationality.
  FILTER(?directorNationality = wd:Q30)  # United States of America
  FILTER EXISTS {
    ?donovanFilm wdt:P31 wd:Q11424; # instance of film
                 rdfs:label "The Death and Life of John F. Donovan"@en;
                 wdt:P161 ?actress.
  }
  BIND(true AS ?starredInDonovan)
} LIMIT 10

